30	import { LocalStorageAdapter } from "../../infrastructure/persistence/Storage";
31	import { StorageCardRepository } from "../../infrastructure/persistence/StorageCardRepository";
32	import { StorageLearnerStateRepository } from "../../infrastructure/persistence/StorageLearnerStateRepository";
33	
34	const storage = new LocalStorageAdapter();
35	const cardRepo = new StorageCardRepository(storage);
36	const apprenticeService = new ApprenticeService(cardRepo);
37	const leechService = new LeechService(cardRepo);
