45	const vocabularyService = new VocabularyService(
46		cardRepo,
47		stateRepo,
48		vocabularyData as VocabEntry[],
49	);
50	const grammarService = new GrammarService(
51		cardRepo,
52		grammarData as unknown as GrammarEntry[],
53		apprenticeService,
54		vocabularyData as VocabEntry[],
55	);
56	const sentenceService = new SentenceService(
57		cardRepo,
58		sentenceData as unknown as SentenceEntry[],
59		vocabularyService,
60		apprenticeService,
61	);
62	const notificationScheduler = new NotificationScheduler();
63	const achievementService = new AchievementService();
64	
65	const lessonUseCase = new StartLessonUseCase(
66		learningService,
67		vocabularyService,
68		grammarService,
69		sentenceService,
70	);
71	const reviewUseCase = new ConductReviewUseCase(
72		reviewService,
73		notificationScheduler,
74	);
75	const dashboardUseCase = new QueryDashboardUseCase(
76		cardRepo,
77		apprenticeService,
78		leechService,
79	);
80	const dataUseCase = new ManageDataUseCase(stateRepo);
81	const itemsUseCase = new ManageItemsUseCase(cardRepo);
82	
83	export interface AppContextValue {
84		state: LearnerState;
85		refresh: () => void;
86		lesson: StartLessonUseCase;
87		review: ConductReviewUseCase;
88		dashboard: QueryDashboardUseCase;
89		data: ManageDataUseCase;
90		items: ManageItemsUseCase;
91		vocab: VocabularyService;
92		checkAchievements: (summary: SessionSummary) => string[];
93	}
94	
95	export const AppContext = createContext<AppContextValue | null>(null);
96	
97	export function AppProvider({ children }: { children: ReactNode }) {
98		const [state, setState] = useState<LearnerState>(() => storage.load());
99	
100		const refresh = useCallback(() => {
101			setState(storage.load());
102		}, []);
103	
104		const checkAchievements = useCallback((summary: SessionSummary): string[] => {
105			const freshState = storage.load();
106			const newIds = achievementService.checkNewAchievements(freshState, summary);
107			for (const id of newIds) {
