131				review: reviewUseCase,
132				dashboard: dashboardUseCase,
133				data: dataUseCase,
134				items: itemsUseCase,
135				vocab: vocabularyService,
136				checkAchievements,
137			}),
138			[state, refresh, checkAchievements],
139		);
