1	import {
2		forwardRef,
3		useCallback,
4		useEffect,
5		useImperativeHandle,
6		useRef,
7	} from "react";
8	
9	export interface DrawingCanvasHandle {
10		clear(): void;
11		isEmpty(): boolean;
12	}
13	
14	interface Props {
15		width?: number;
16		height?: number;
17		strokeColor?: string;
18		strokeWidth?: number;
19		disabled?: boolean;
20	}
21	
22	export const DrawingCanvas = forwardRef<DrawingCanvasHandle, Props>(
23		function DrawingCanvas(
24			{
25				width = 280,
26				height = 280,
27				strokeColor = "var(--color-text)",
28				strokeWidth = 4,
29				disabled = false,
30			},
31			ref,
32		) {
33			const canvasRef = useRef<HTMLCanvasElement>(null);
34			const isDrawingRef = useRef(false);
35			const hasStrokesRef = useRef(false);
36	
37			const clear = useCallback(() => {
38				const canvas = canvasRef.current;
39				if (!canvas) return;
40				const ctx = canvas.getContext("2d");
41				if (ctx) ctx.clearRect(0, 0, canvas.width, canvas.height);
42				hasStrokesRef.current = false;
43			}, []);
44	
45			useImperativeHandle(ref, () => ({
46				clear,
47				isEmpty: () => !hasStrokesRef.current,
48			}));
49	
50			const getPos = useCallback((e: PointerEvent) => {
51				const canvas = canvasRef.current;
52				if (!canvas) return { x: 0, y: 0 };
53				const rect = canvas.getBoundingClientRect();
54				const scaleX = canvas.width / rect.width;
55				const scaleY = canvas.height / rect.height;
56				return {
57					x: (e.clientX - rect.left) * scaleX,
58					y: (e.clientY - rect.top) * scaleY,
59				};
60			}, []);
61	
62			useEffect(() => {
63				const canvas = canvasRef.current;
64				if (!canvas || disabled) return;
65	
66				const ctx = canvas.getContext("2d");
67				if (ctx) {
68					ctx.lineCap = "round";
69					ctx.lineJoin = "round";
70					ctx.lineWidth = strokeWidth;
71					ctx.strokeStyle = strokeColor;
72				}
73	
74				const onPointerDown = (e: PointerEvent) => {
75					isDrawingRef.current = true;
76					canvas.setPointerCapture(e.pointerId);
77					if (!ctx) return;
