1	import { useCallback, useEffect, useRef, useState } from "react";
2	import { useNavigate } from "react-router";
3	import { Button } from "@/presentation/components/ui/button";
4	import { Card } from "@/presentation/components/ui/card";
5	import { Progress } from "@/presentation/components/ui/progress";
6	import { ratingFromCorrectness } from "../../domain/shared/ratingFromCorrectness";
7	import type { RecallRating, SessionSummary } from "../../domain/shared/types";
8	import { Accuracy } from "../../domain/srs/value-objects/Accuracy";
9	import type { VocabularyCard } from "../../domain/vocabulary/types";
10	import { SectionHeader } from "../components/atoms/SectionHeader";
11	import { SessionStatGrid } from "../components/molecules/SessionStatGrid";
12	import { AchievementBadge } from "../components/organisms/AchievementBadge";
13	import { DrawingQuiz } from "../components/organisms/DrawingQuiz";
14	import { Flashcard } from "../components/organisms/Flashcard";
15	import { MultipleChoice } from "../components/organisms/MultipleChoice";
16	import { SentenceBuilder } from "../components/organisms/SentenceBuilder";
17	import type { Promotion } from "../components/organisms/StagePromotionPanel";
18	import { StagePromotionPanel } from "../components/organisms/StagePromotionPanel";
19	import { useApp } from "../hooks/useApp";
20	import { useReviewSession } from "../hooks/useReviewSession";
21	
22	interface ReviewResult {
23		cardId: string;
24		rating: RecallRating;
25		beforeStage: string;
26		afterStage: string;
27	}
28	
29	export function ReviewPage() {
30		const { review, refresh, checkAchievements } = useApp();
31		const navigate = useNavigate();
32		const [done, setDone] = useState(false);
33		const [sessionCorrect, setSessionCorrect] = useState(0);
34		const [sessionTotal, setSessionTotal] = useState(0);
35		const resultsRef = useRef<ReviewResult[]>([]);
36		const startedRef = useRef(false);
37		const achievementsRef = useRef<string[] | null>(null);
38		const summaryRef = useRef<SessionSummary | null>(null);
39		// Map cardId -> question captured from session cards before session ends
40		const cardQuestionsRef = useRef<Map<string, string>>(new Map());
41	
42		const startSession = useCallback(
43			(maxCards?: number) => review.startSession(undefined, maxCards),
44			[review],
45		);
46		const recordReview = useCallback(
47			(cardId: string, rating: RecallRating): string => {
48				const newStage = review.recordReview(cardId, rating);
49				refresh();
50				return newStage;
51			},
52			[review, refresh],
53		);
54		const endSession = useCallback(
55			(session: Parameters<typeof review.endSession>[0]) => {
56				const summary = review.endSession(session);
57				refresh();
58				return summary;
59			},
60			[review, refresh],
61		);
62	
63		const reviewSession = useReviewSession(
64			startSession,
65			recordReview,
66			endSession,
67		);
68	
69		// Capture card questions whenever the session is active so we can display them after completion
70		useEffect(() => {
71			if (reviewSession.session) {
72				for (const quizCard of reviewSession.session.cards) {
73					cardQuestionsRef.current.set(quizCard.card.id, quizCard.card.question);
74				}
75			}
76		}, [reviewSession.session]);
77	
78		const handleAdvance = useCallback(
79			(rating: RecallRating) => {
80				setSessionTotal((t) => t + 1);
81				if (rating >= 3) {
82					setSessionCorrect((c) => c + 1);
83				}
84				const result = reviewSession.handleReviewAdvance(rating);
85				if (result?.status === "complete") {
86					resultsRef.current = result.results;
87					summaryRef.current = result.summary ?? null;
88					setDone(true);
89				}
90			},
91			[reviewSession],
92		);
93	
94		const handleMcAnswer = useCallback(
95			(correct: boolean, responseTimeMs?: number) => {
96				handleAdvance(ratingFromCorrectness(correct, responseTimeMs));
97			},
98			[handleAdvance],
99		);
100	
101		// Auto-start on mount
102		useEffect(() => {
103			if (!startedRef.current) {
104				startedRef.current = true;
105				const s = reviewSession.startReview();
106				if (s.cards.length === 0) {
107					navigate("/");
108				}
109			}
110		}, [reviewSession, navigate]);
111	
112		if (!reviewSession.session && !done) return null;
113	
114		if (done) {
115			const results = resultsRef.current;
116			const correctCount = results.filter((r) => r.rating >= 3).length;
117			const accuracy = Accuracy.fromCounts(correctCount, results.length);
118	
119			if (achievementsRef.current === null && summaryRef.current) {
120				achievementsRef.current = checkAchievements(summaryRef.current);
121				refresh();
122			}
123	
124			// Build stage promotions only for cards that actually changed stage
125			const promotions: Promotion[] = results
126				.filter((r) => r.afterStage !== r.beforeStage)
127				.map((r) => ({
128					cardQuestion: cardQuestionsRef.current.get(r.cardId) ?? r.cardId,
129					newStage: r.afterStage,
130				}));
131	
132			return (
133				<div className="space-y-6 py-8">
134					<div className="text-center">
135						<div className="text-5xl mb-3">
136							{accuracy.percentage >= 80 ? "✦" : "◈"}
137						</div>
138						<h1
139							className="text-2xl font-semibold"
140							style={{ color: "var(--color-text)" }}
141						>
142							Review Complete
143						</h1>
144					</div>
145	
146					{/* Stats grid */}
147					<SessionStatGrid
148						totalLabel="Reviewed"
149						total={results.length}
150						correct={correctCount}
151						accuracy={accuracy.percentage}
152					/>
153	
154					{/* Stage promotions */}
155					<StagePromotionPanel promotions={promotions} />
156	
157					{/* Newly unlocked achievements */}
158					{(achievementsRef.current ?? []).length > 0 && (
159						<Card className="p-4">
160							<SectionHeader className="mb-3">
161								Achievement Unlocked!
162							</SectionHeader>
163							<div className="flex gap-4 flex-wrap justify-center">
164								{(achievementsRef.current ?? []).map((id) => (
165									<AchievementBadge key={id} id={id} unlocked size="sm" />
166								))}
167							</div>
168						</Card>
169					)}
170	
171					{/* Actions */}
172					<div className="space-y-3">
173						{review.getDueCount() > 0 && (
174							<Button
175								className="w-full"
176								onClick={() => {
177									startedRef.current = false;
178									achievementsRef.current = null;
179									summaryRef.current = null;
180									setDone(false);
181								}}
182							>
183								Review More ({review.getDueCount()} due)
184							</Button>
185						)}
186						<Button
187							variant="outline"
188							className="w-full"
189							onClick={() => navigate("/")}
190						>
191							Go to Dashboard
192						</Button>
193					</div>
194				</div>
195			);
196		}
197	
198		if (!reviewSession.currentCard || !reviewSession.session) return null;
199	
200		const liveAccuracy =
201			sessionTotal > 0
202				? `${Math.round((sessionCorrect / sessionTotal) * 100)}%`
203				: "—";
204	
205		return (
206			<div>
207				{/* Session header HUD */}
208				<div className="mb-4">
209					<div className="flex items-center justify-between mb-2">
210						<span
211							className="text-sm font-semibold"
212							style={{ color: "var(--color-text)" }}
213						>
214							Review Session
215						</span>
216						<span
217							className="text-sm"
218							style={{ color: "var(--color-text-muted)" }}
219						>
220							{reviewSession.cardIdx + 1} / {reviewSession.session.cards.length}
221						</span>
222						<span
223							className="text-sm"
224							style={{ color: "var(--color-text-muted)" }}
225						>
226							Acc: {liveAccuracy}
227						</span>
228						<button
229							type="button"
230							onClick={() => navigate("/")}
231							className="text-lg leading-none"
232							style={{ color: "var(--color-text-muted)" }}
233							title="End session"
234						>
235							✕
236						</button>
237					</div>
238					<Progress
239						value={
240							((reviewSession.cardIdx + 1) / reviewSession.session.cards.length) *
241							100
242						}
243						className="h-1.5"
244					/>
245				</div>
246	
247				{"property" in reviewSession.currentCard.card &&
248				((reviewSession.currentCard.card as unknown as VocabularyCard)
249					.property === "spelling" ||
250					(reviewSession.currentCard.card as unknown as VocabularyCard)
251						.property === "spellingFromAudio") ? (
252					<SentenceBuilder
253						card={reviewSession.currentCard.card as unknown as VocabularyCard}
254						onAnswer={handleMcAnswer}
255					/>
256				) : reviewSession.currentCard.mode === "multipleChoice" ? (
257					<MultipleChoice
258						card={reviewSession.currentCard.card}
259						onAnswer={handleMcAnswer}
260					/>
261				) : "property" in reviewSession.currentCard.card &&
262					(reviewSession.currentCard.card as unknown as VocabularyCard)
263						.property === "audioRecognition" &&
264					"symbolCharacter" in reviewSession.currentCard.card &&
265					(
266						reviewSession.currentCard.card as unknown as {
267							symbolCharacter: string;
268						}
269					).symbolCharacter === "" ? (
270					<DrawingQuiz
271						card={reviewSession.currentCard.card}
272						onRate={handleAdvance}
273					/>
274				) : (
275					<Flashcard
276						card={reviewSession.currentCard.card}
277						onRate={handleAdvance}
278					/>
279				)}
280			</div>
281		);
