 * singleton and must never hold a round.
 *
 * Deliberately reads only `game` from `useApp()`: no `refresh()`, no
 * `checkAchievements`, nothing that could write the SRS blob. A practice
 * round must leave `thai-srs-state` byte-identical.
 */
export function GamePage() {
	const { game } = useApp();
	const navigate = useNavigate();

	const [phase, setPhase] = useState<GamePhase>("setup");
	const [inputMode, setInputMode] = useState<GameInputMode>("draw");
	const [items, setItems] = useState<GameItem[]>([]);
	const [ratings, setRatings] = useState<GameRatingRecord[]>([]);
	const [currentIndex, setCurrentIndex] = useState(0);
	const [summary, setSummary] = useState<GameRoundSummaryData | null>(null);
	// Guards against a rating landing twice for one item (a stray global
	// keypress on top of a click) advancing past the next item unseen.
	const ratedIndexRef = useRef(-1);

	const eligibleCount = useMemo(
		() => (phase === "setup" ? countEligibleItems(game) : 0),
		[game, phase],
	);
	const [countInput, setCountInput] = useState<string>(() =>
		eligibleCount > 0
			? String(Math.min(DEFAULT_ITEM_COUNT, eligibleCount))
			: "",
	);
	const history = useMemo(
		() => (phase === "setup" ? game.getHistory() : null),
		[game, phase],
	);

	const parsedCount = countInput === "" ? Number.NaN : Number(countInput);
	const countValid =
		Number.isInteger(parsedCount) &&
		parsedCount >= 1 &&
		parsedCount <= eligibleCount;

	const handleStart = useCallback(() => {
		const roundItems = game.startRound({
			pools: GAME_POOLS,
			itemCount: parsedCount,
			prioritizeWeakItems: false,
			inputMode,
		});
		if (roundItems.length === 0) return;
		setItems(roundItems);
		setRatings([]);
		setCurrentIndex(0);
		setSummary(null);
		ratedIndexRef.current = -1;
		setPhase("playing");
	}, [game, parsedCount, inputMode]);

	const handleRate = useCallback(
		(rating: RecallRating) => {
			if (ratedIndexRef.current >= currentIndex) return;
			ratedIndexRef.current = currentIndex;

			const nextRatings = game.recordRating(
				items,
				ratings,
				currentIndex,
				rating,
			);
			setRatings(nextRatings);

			if (currentIndex + 2 < items.length) {
				setCurrentIndex(currentIndex + 1);
				return;
			}

			const roundSummary = game.finishRound(nextRatings);
			game.saveHistory(
				{ pools: GAME_POOLS, itemCount: items.length },
				roundSummary,
			);
			setSummary(roundSummary);
			setPhase("summary");
		},
		[game, items, ratings, currentIndex],
	);

	if (phase === "playing") {
		const item = items[currentIndex];
		if (!item) return null;

		return (
			<div>
				<div className="mb-4 flex items-center justify-between">
					<span
						className="text-sm font-semibold"
						style={{ color: "var(--color-text)" }}
					>
						Practice Round
					</span>
					<span className="text-sm" style={{ color: "var(--color-text-muted)" }}>
						{currentIndex + 1} / {items.length}
					</span>
					<button
						type="button"
						onClick={() => navigate("/")}
						className="text-lg leading-none"
						style={{ color: "var(--color-text-muted)" }}
						aria-label="End round"
						title="End round"
					>
						✕
					</button>
				</div>

				{item.challengeDirection === "dictation" ? (
					<SymbolDictationChallenge
						item={item}
						inputMode={inputMode}
						onRate={handleRate}
					/>
				) : (
					<SymbolReadingChallenge item={item} onRate={handleRate} />
				)}
			</div>
		);
	}

	if (phase === "summary" && summary) {
		return (
			<div className="space-y-6 py-8">
				<GameRoundSummary summary={summary} itemCount={items.length} />
				<div className="space-y-3">
					<Button className="w-full" onClick={() => setPhase("setup")}>
						Play Again
					</Button>
					<Button
						variant="outline"
						className="w-full"
						onClick={() => navigate("/")}
					>
						Go to Dashboard
					</Button>
				</div>
			</div>
		);
	}

	return (
		<div className="space-y-6 py-4">
			<div>
				<h1
					className="text-2xl font-semibold"
					style={{ color: "var(--color-text)" }}
				>
					Practice Game
				</h1>
				<p
					className="text-sm mt-1"
					style={{ color: "var(--color-text-muted)" }}
				>
					Self-graded drilling over your introduced symbols — it never changes
					your review schedule.
				</p>
			</div>

			{eligibleCount === 0 ? (
				<p
					className="rounded-xl p-4 text-sm"
					style={{
						background: "var(--color-surface-2)",
						color: "var(--color-text-muted)",
					}}
				>
					No symbols to practice yet — complete a script lesson first.
				</p>
			) : (
				<div
					className="rounded-xl p-4 space-y-4"
					style={{
						border: "1px solid var(--color-border)",
						background: "var(--color-surface)",
					}}
				>
					<div>
						<label
							htmlFor="game-item-count"
							className="block text-sm font-semibold mb-1"
							style={{ color: "var(--color-text)" }}
						>
							Items per round
						</label>
						<input
							id="game-item-count"
							type="number"
							min={1}
							max={eligibleCount}
							step={1}
							value={countInput}
							onChange={(e) => setCountInput(e.target.value)}
							className="w-full rounded-xl p-3"
							style={{
								border: "1px solid var(--color-border)",
								background: "var(--color-surface-2)",
								color: "var(--color-text)",
							}}
						/>
						<p
							className="text-xs mt-1"
							style={{ color: "var(--color-text-muted)" }}
						>
							Whole number from 1 to {eligibleCount}
						</p>
					</div>

					<fieldset>
						<legend
							className="text-sm font-semibold mb-1"
							style={{ color: "var(--color-text)" }}
						>
							Input mode
						</legend>
						<div className="flex gap-4">
							<span className="flex items-center gap-2">
								<input
									id="game-input-draw"
									type="radio"
									name="game-input-mode"
									checked={inputMode === "draw"}
									onChange={() => setInputMode("draw")}
								/>
								<label
									htmlFor="game-input-draw"
									className="text-sm"
									style={{ color: "var(--color-text)" }}
								>
									Draw on canvas
								</label>
							</span>
							<span className="flex items-center gap-2">
								<input
									id="game-input-paper"
									type="radio"
									name="game-input-mode"
									checked={inputMode === "paper"}
									onChange={() => setInputMode("paper")}
								/>
								<label
									htmlFor="game-input-paper"
									className="text-sm"
									style={{ color: "var(--color-text)" }}
								>
									Write on paper
								</label>
							</span>
						</div>
					</fieldset>

					<Button
						className="w-full"
						disabled={!countValid}
						onClick={handleStart}
					>
						Start Round
					</Button>
				</div>
			)}

			{history && (
				<div>
					<SectionHeader className="mb-3">Recent Rounds</SectionHeader>
					<GameHistoryList result={history} />
				</div>
			)}
		</div>
	);
}

import { useCallback, useEffect, useRef, useState } from "react";
import type { SymbolGameItem } from "../../../domain/game/types";
import type { RecallRating } from "../../../domain/shared/types";
import { RatingButtons } from "./RatingButtons";

interface Props {
	item: SymbolGameItem;
	onRate: (rating: RecallRating) => void;
}

/**
 * See it, say it: the symbol is shown, the learner says it aloud, and the
 * reveal plays the pronunciation and shows the name. No audio is
 * constructed before the reveal — hearing it first would answer the
 * challenge.
 *
 * Reset is keyed on the item's own identity (`symbolCharacter`) — two
 * consecutive same-direction items reuse this component instance without a
 * remount (see CONTEXT.md).
 */
export function SymbolReadingChallenge({ item, onRate }: Props) {
	const [revealed, setRevealed] = useState(false);
	const audioRef = useRef<HTMLAudioElement | null>(null);

	const playAudio = useCallback(() => {
		if (!item.audioUrl) return;
		if (audioRef.current) {
			audioRef.current.pause();
			audioRef.current.currentTime = 0;
		}
		const audio = new Audio(item.audioUrl);
		audioRef.current = audio;
		audio.play().catch(() => {});
	}, [item.audioUrl]);

	// Reset state on item change; stop any reveal audio still playing.
	// biome-ignore lint/correctness/useExhaustiveDependencies: the item's identity drives the reset
	useEffect(() => {
		setRevealed(false);
		return () => {
			audioRef.current?.pause();
			audioRef.current = null;
		};
	}, [item.symbolCharacter]);

	const handleReveal = useCallback(() => {
		setRevealed(true);
		playAudio();
	}, [playAudio]);

	return (
		<div className="space-y-6">
			<div
				className="rounded-xl p-4"
				style={{
					border: "1px solid var(--color-border)",
					background: "var(--color-surface)",
				}}
			>
				<p
					className="text-center text-lg mb-4"
					style={{ color: "var(--color-text-muted)" }}
				>
					Say this symbol aloud
				</p>
				<p
					className="text-center text-7xl font-bold py-6"
					style={{ color: "var(--color-text)" }}
				>
					{item.promptText}
				</p>
			</div>

			{!revealed ? (
				<button
					type="button"
					onClick={handleReveal}
					className="w-full py-4 rounded-xl text-lg font-semibold transition-colors"
					style={{
						background: "var(--color-surface-2)",
						color: "var(--color-text)",
					}}
				>
					Show Answer
				</button>
			) : (
				<div
					style={{ animation: "slideUp 0.25s ease-out" }}
					className="space-y-6"
				>
					<div
						className="text-center py-4 rounded-xl"
						style={{ background: "var(--color-surface-2)" }}
					>
						<p
							className="text-2xl font-bold"
							style={{ color: "var(--color-primary)" }}
						>
							{item.correctAnswer}
						</p>
						{item.audioUrl && (
							<button
								type="button"
								onClick={playAudio}
								className="mt-3 inline-flex items-center justify-center w-12 h-12 rounded-full text-2xl transition-colors"
								style={{
									background: "var(--color-surface)",
									color: "var(--color-primary)",
								}}
								aria-label="Replay pronunciation"
							>
								🔊
							</button>
						)}
					</div>
					<RatingButtons onRate={onRate} />
				</div>
			)}
		</div>
	);
}

