					className="text-2xl font-semibold"
					style={{ color: "var(--color-text)" }}
				>
					Practice Game
				</h1>
				<p
					className="text-sm mt-1"
					style={{ color: "var(--color-text-muted)" }}
				>
					Self-graded drilling over your introduced symbols — it never changes
					your review schedule.
				</p>
			</div>

			{eligibleCount === 0 ? (
				<p
					className="rounded-xl p-4 text-sm"
					style={{
						background: "var(--color-surface-2)",
						color: "var(--color-text-muted)",
					}}
				>
					No symbols to practice yet — complete a script lesson first.
				</p>
			) : (
				<div
					className="rounded-xl p-4 space-y-4"
					style={{
						border: "1px solid var(--color-border)",
						background: "var(--color-surface)",
					}}
				>
					<div>
						<label
							htmlFor="game-item-count"
							className="block text-sm font-semibold mb-1"
							style={{ color: "var(--color-text)" }}
						>
							Items per round
						</label>
						<input
							id="game-item-count"
							type="number"
							min={1}
							max={eligibleCount}
							step={1}
							value={countInput}
							onChange={(e) => setCountInput(e.target.value)}
							className="w-full rounded-xl p-3"
							style={{
								border: "1px solid var(--color-border)",
								background: "var(--color-surface-2)",
								color: "var(--color-text)",
							}}
						/>
						<p
							className="text-xs mt-1"
							style={{ color: "var(--color-text-muted)" }}
						>
							Whole number from 1 to {eligibleCount}
						</p>
					</div>

					<fieldset>
						<legend
							className="text-sm font-semibold mb-1"
							style={{ color: "var(--color-text)" }}
						>
							Input mode
						</legend>
						<div className="flex gap-4">
							<span className="flex items-center gap-2">
								<input
									id="game-input-draw"
									type="radio"
									name="game-input-mode"
									checked={inputMode === "draw"}
									onChange={() => setInputMode("draw")}
								/>
								<label
									htmlFor="game-input-draw"
									className="text-sm"
									style={{ color: "var(--color-text)" }}
								>
									Draw on canvas
								</label>
							</span>
							<span className="flex items-center gap-2">
								<input
									id="game-input-paper"
									type="radio"
									name="game-input-mode"
									checked={inputMode === "paper"}
									onChange={() => setInputMode("paper")}
								/>
								<label
									htmlFor="game-input-paper"
									className="text-sm"
									style={{ color: "var(--color-text)" }}
								>
									Write on paper
								</label>
							</span>
						</div>
					</fieldset>

					<Button
						className="w-full"
						disabled={!countValid}
						onClick={handleStart}
					>
						Start Round
					</Button>
				</div>
			)}

			{history && (
				<div>
					<SectionHeader className="mb-3">Recent Rounds</SectionHeader>
					<GameHistoryList result={history} />
				</div>
			)}
		</div>
	);
}

